            --ink: #241915;
            --paper: #f8f1e7;
            --cinnabar: #a63a2c;
            --gold: #b78a42;
            --pine: #315247;
            --line: rgba(36, 25, 21, 0.1);
            --shadow: 0 18px 48px rgba(70, 41, 24, 0.12);
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            font-family: Georgia, "Times New Roman", serif;
            color: var(--ink);
            background:
                radial-gradient(circle at top, rgba(183, 138, 66, 0.16), transparent 34%),
                linear-gradient(180deg, #f5e7d6 0%, var(--paper) 42%, #fbf7f1 100%);
            line-height: 1.72;
        }

        a { color: inherit; text-decoration: none; }

        .container {
            width: min(1120px, calc(100% - 40px));
            margin: 0 auto;
        }

        .topbar {
            position: sticky;
            top: 0;
            z-index: 10;
            backdrop-filter: blur(14px);
            background: rgba(248, 241, 231, 0.88);
            border-bottom: 1px solid rgba(36, 25, 21, 0.08);
        }

        .topbar-inner {
            min-height: 74px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 18px;
        }

        .brand {
            display: flex;
            flex-direction: column;
            gap: 2px;
        }

        .brand-mark {
            font-size: 13px;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: var(--cinnabar);
        }

        .brand-name {
            font-size: 24px;
            font-weight: 700;
        }

        .nav {
            display: flex;
            gap: 18px;
            font-size: 14px;
            color: rgba(36, 25, 21, 0.78);
            flex-wrap: wrap;
            justify-content: flex-end;
        }

        .hero {
            padding: 74px 0 56px;
        }

        .hero-grid {
            display: grid;
            grid-template-columns: minmax(0, 1.12fr) minmax(320px, 0.88fr);
            gap: 30px;
            align-items: stretch;
        }

        .hero-copy,
        .hero-panel,
        .story-card,
        .plan-card,
        .carrier-card,
        .step,
        .faq-item,
        .closing-card {
            background: rgba(255, 253, 248, 0.9);
            border: 1px solid rgba(36, 25, 21, 0.08);
            box-shadow: var(--shadow);
        }

        .hero-copy {
            padding: 44px;
            border-radius: 28px;
        }

        .eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            font-size: 12px;
            letter-spacing: 0.18em;
            text-transform: uppercase;
            color: var(--gold);
            margin-bottom: 18px;
        }

        .eyebrow::before {
            content: "";
            width: 34px;
            height: 1px;
            background: currentColor;
        }

