            font-size: clamp(36px, 6vw, 64px);
            line-height: 1.05;
            margin-bottom: 18px;
        }

        .hero-copy p,
        .section-head p,
        .story-card p,
        .plan-card p,
        .carrier-card p,
        .step p,
        .faq-item p {
            color: rgba(36, 25, 21, 0.76);
        }

