        const focusToPlan = {
            balance: "elements",
            career: "career",
            wealth: "wealth",
            love: "love",
            protection: "protection"
        };

        function syncSelection() {
            document.querySelectorAll("[data-plan]").forEach((button) => {
                button.classList.toggle("selected", button.dataset.plan === selectedPlan);
            });
            document.querySelectorAll("[data-carrier]").forEach((button) => {
                button.classList.toggle("selected", button.dataset.carrier === selectedCarrier);
            });

            document.getElementById("planKey").value = selectedPlan;
