            document.getElementById("carrierKey").value = selectedCarrier;
            document.getElementById("carrierName").value = carriers[selectedCarrier];
            document.getElementById("selectionLabel").textContent = plans[selectedPlan] + " - " + carriers[selectedCarrier];
        }

        function selectPlan(key) {
            selectedPlan = key;
            syncSelection();
        }

        function selectCarrier(key) {
            selectedCarrier = key;
            syncSelection();
        }

        function applyIncomingState() {
            const incoming = { ...window.ReadingState.read(), ...window.ReadingState.fromQuery() };
            const mappedPlan = focusToPlan[incoming.focus] || incoming.plan_key;

            if (mappedPlan && plans[mappedPlan]) selectedPlan = mappedPlan;
            if (incoming.carrier && carriers[incoming.carrier]) selectedCarrier = incoming.carrier;
            if (incoming.birth_date) document.getElementById("birthDate").value = incoming.birth_date;
            if (incoming.birth_time) document.getElementById("birthTime").value = incoming.birth_time;
            if (incoming.notes) document.getElementById("notes").value = incoming.notes;
            if (incoming.full_name && !document.getElementById("notes").value.includes("Client name:")) {
                document.getElementById("notes").value = `Client name: ${incoming.full_name}\n${document.getElementById("notes").value}`.trim();
            }
        }

        const orderForm = document.getElementById("orderForm");
