            formStatus.textContent = message;
            formStatus.className = "form-status visible " + type;
        }

        function persistReadingState() {
            const notesValue = document.getElementById("notes").value;
            const storedName = (notesValue.match(/Client name:\s*(.+)/) || [])[1] || "";
            window.ReadingState.merge({
                focus: Object.keys(focusToPlan).find((key) => focusToPlan[key] === selectedPlan) || "balance",
                plan_key: selectedPlan,
                carrier: selectedCarrier,
                birth_date: document.getElementById("birthDate").value,
                birth_time: document.getElementById("birthTime").value,
                notes: notesValue,
